#include <stdio.h>
#include <stdarg.h>

void shout(const char *first, ...) {
    va_list args;
    va_start(args, first);
    const char *sep = "";
    for (const char *w = first; w != NULL; w = va_arg(args, const char *)) {
        printf("%s%s!", sep, w);
        sep = " ";
    }
    va_end(args);
    printf("\n");
}

int main(void) {
    shout("red", "alert", NULL);
    shout("mayday", NULL);
    return 0;
}

