#include <stdio.h>
#include <stdarg.h>
#include <string.h>

int count_long(int min_len, ...) {
    va_list args;
    va_start(args, min_len);
    int count = 0;
    for (const char *w = va_arg(args, const char *); w != NULL; w = va_arg(args, const char *)) {
        if ((int)strlen(w) >= min_len) count++;
    }
    va_end(args);
    return count;
}

int main(void) {
    int min_len;
    char w1[32], w2[32], w3[32];
    scanf("%d %31s %31s %31s", &min_len, w1, w2, w3);
    printf("%d\n", count_long(min_len, w1, w2, w3, NULL));
    printf("%d\n", count_long(min_len, w2, NULL));
    printf("%d\n", count_long(min_len, NULL));
    return 0;
}

