#include <stdio.h>
#include <stdarg.h>

void mini_print(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    for (const char *p = fmt; *p != '\0'; p++) {
        if (*p != '%') {
            putchar(*p);
            continue;
        }
        p++;
        if (*p == 'd') printf("%d", va_arg(args, int));
        else if (*p == 's') fputs(va_arg(args, const char *), stdout);
        else if (*p == 'c') putchar(va_arg(args, int));
        else putchar(*p);
    }
    va_end(args);
}

int main(void) {
    char name[32];
    int n;
    scanf("%31s %d", name, &n);
    mini_print("Crew %s has %d drones%c\n", name, n, '!');
    mini_print("100%% ready\n");
    return 0;
}

